namespace sv_2edeb938cfa34507999aa3e86963e2dd.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — East Coast"),
        new("WH-003", "Warehouse C — West Coast"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_2edeb938cfa34507999aa3e86963e2dd.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// Components subscribe to OnAlertCountChanged to receive updates
/// triggered by any component's polling cycle.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();
    private int _lastAlertCount;

    public int CurrentAlertCount => _lastAlertCount;

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by any polling component. Updates the shared count and notifies ALL subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        _lastAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

