<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @(Warehouse.AvailableWarehouses.FirstOrDefault(w => w.Id == Warehouse.CurrentWarehouseId)?.Name ?? Warehouse.CurrentWarehouseId)
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <span class="badge bg-danger rounded-pill">@AlertService.CurrentAlertCount</span>
        </h5>
        <p class="text-muted">
            Polling every 10 seconds for items below minimum stock levels.
        </p>
        @if (_isPolling)
        {
            <span class="text-success"><em>● Polling active</em></span>
        }
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        StopPolling();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(Warehouse.CurrentWarehouseId);
        StateHasChanged();

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(Warehouse.CurrentWarehouseId);
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose or warehouse change
        }
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling with new warehouse
        await StartPollingAsync();
        StateHasChanged();
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
        _isPolling = false;
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        StopPolling();
    }
}

